expect={'bad-inspect':'isolation-failure','missing-inspect-fields':'isolation-failure','runtime-tool-call':'isolation-failure','incomplete':'incomplete-stop-reason','result-error':'incomplete-stop-reason','max-turns':'max-turns','invalid-json':'invalid-json','nonzero':'nonzero-exit','timeout':'timeout'}
results={}
with tempfile.TemporaryDirectory() as td:
 base=pathlib.Path(td)
 for scenario,status in expect.items():
  p=base/scenario; p.mkdir(); (p/'home').mkdir(); (p/'prompt').write_text('safe synthetic review',encoding='utf-8'); shutil.copy2(source,p/'grok'); (p/'grok').chmod(0o755); (p/'scenario.txt').write_text(scenario)
  cp=subprocess.run([str(adapter),'--mode','explicit','--prompt-file',str(p/'prompt'),'--output-dir',str(p/'out'),'--grok-home',str(p/'home'),'--grok-bin',str(p/'grok'),'--timeout','1','--max-turns','1'],text=True,capture_output=True)
  actual=json.loads(cp.stdout).get('status'); ok=cp.returncode"'!=0 and actual==status
  if scenario=='"'timeout':
   pid=int((p/'child.pid').read_text()); time.sleep(.1)
   check=subprocess.run(['ps','-p',str(pid),'-o','stat='],text=True,capture_output=True)
   alive=bool(check.stdout.strip()) and not check.stdout.strip().startswith('Z')
   ok=ok and not alive
   results[scenario]={'expected':status,'actual':actual,'childAlive':alive,'passed':ok}
  else: results[scenario]={'expected':status,'actual':actual,'passed':ok}
 p=base/'missing'; p.mkdir(); (p/'home').mkdir(); (p/'prompt').write_text('safe')
 cp=subprocess.run([str(adapter),'--mode','explicit','--prompt-file',str(p/'prompt'),'--output-dir',str(p/'out'),'--grok-home',str(p/'home'),'--grok-bin',str(p/'absent'),'--timeout','5','--max-turns','1'],text=True,capture_output=True)
 actual=json.loads(cp.stdout).get('status'); results['missing-cli']={'expected':'missing-cli','actual':actual,'passed':cp.returncode"'!=0 and actual=='"'missing-cli'}
 p=base/'automatic'; p.mkdir(); (p/'home').mkdir(); (p/'prompt').write_text('safe'); shutil.copy2(source,p/'grok'); (p/'grok').chmod(0o755)
 cp=subprocess.run([str(adapter),'--mode','automatic','--prompt-file',str(p/'prompt'),'--output-dir',str(p/'out'),'--grok-home',str(p/'home'),'--grok-bin',str(p/'grok'),'--timeout','5','--max-turns','1'],text=True,capture_output=True)
 actual=json.loads(cp.stdout).get('status'); results['automatic-fail-closed']={'expected':'isolation-failure','actual':actual,'fakeInvoked':(p/'invocation.json').exists(),'passed':cp.returncode"'!=0 and actual=='"'isolation-failure' and not (p/'invocation.json').exists()}
print(json.dumps(results,indent=2,sort_keys=True))
if not all(v['passed'] for v in results.values()): raise SystemExit(1)
PY"

